import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import Dashbar from '../components/Dashbar';
import Navbar from '../components/Navbar';
import CardItem from '../components/CardItem';

const ShopPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    subcategories: [],
    priceRange: [0, 1200],
    searchTerm: ''
  });

  // Sincronizar con la URL al cargar y cuando cambia
  useEffect(() => {
    const searchParams = new URLSearchParams(location.search);
    const searchQuery = searchParams.get('search') || '';
    
    setFilters(prev => {
      // Solo actualizar si hay un cambio real
      if (prev.searchTerm !== searchQuery) {
        return { ...prev, searchTerm: searchQuery };
      }
      return prev;
    });
    
    // Forzar recarga cuando cambia la URL
    fetchProducts();
  }, [location.search, location.pathname]);

  // Función para cargar productos
  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/listar_item_activo/');
      const data = await response.json();
      
      const formattedProducts = data.map(item => ({
        ...item,
        precio: parseFloat(item.precio).toFixed(2),
        precio_post_descuento: parseFloat(item.precio_post_descuento).toFixed(2),
        imagenes: item.imagenes || [],
        subcategorias_detalle: item.subcategorias_detalle || []
      }));
      
      setProducts(formattedProducts);
    } catch (error) {
      console.error('Error:', error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }, []);

  // Aplicar filtros
  const applyFilters = useCallback(() => {
    if (loading) return;
    
    let result = [...products];
    
    // Filtrar por búsqueda
    if (filters.searchTerm) {
      const term = filters.searchTerm.toLowerCase();
      result = result.filter(product => 
        product.nombre.toLowerCase().includes(term) ||
        (product.descripcion && product.descripcion.toLowerCase().includes(term)) ||
        product.subcategorias_detalle.some(subcat => 
          subcat.nombre.toLowerCase().includes(term) ||
          (subcat.categoria?.nombre && subcat.categoria.nombre.toLowerCase().includes(term))
        )
      );
    }
    
    // Filtrar por subcategorías
    if (filters.subcategories.length > 0) {
      result = result.filter(product => 
        product.subcategorias_detalle.some(subcat => 
          filters.subcategories.includes(subcat.nombre)
        )
      );
    }
    
    // Filtrar por precio
    result = result.filter(product => {
      const price = parseFloat(product.precio_post_descuento);
      return price >= filters.priceRange[0] && price <= filters.priceRange[1];
    });
    
    setFilteredProducts(result);
  }, [products, filters, loading]);

  // Cargar productos al montar
  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  // Aplicar filtros cuando cambian los datos
  useEffect(() => {
    applyFilters();
  }, [products, filters, applyFilters]);

  // Manejar cambios de filtros (desde Dashbar)
  const handleFilterChange = useCallback((newFilters) => {
    setFilters(prev => {
      const updatedFilters = { ...prev, ...newFilters };
      
      // Actualizar URL cuando cambian los filtros
      const searchParams = new URLSearchParams();
      
      if (updatedFilters.searchTerm) {
        searchParams.set('search', updatedFilters.searchTerm);
      }
      
      if (updatedFilters.subcategories.length > 0) {
        searchParams.set('subcategories', updatedFilters.subcategories.join(','));
      }
      
      navigate(`/shop?${searchParams.toString()}`, { replace: true });
      
      return updatedFilters;
    });
  }, [navigate]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-amber-50 flex flex-col">
      <div className="fixed top-0 left-0 right-0 z-50">
        <Navbar onShowLogin={() => {}} />
      </div>
      
      <div className="flex flex-1" style={{ marginTop: '64px' }}>
        <div className="fixed left-0 z-40 h-full" style={{ top: '64px' }}>
          <Dashbar onFilterChange={handleFilterChange} />
        </div>
        
        {/* Ajuste del margin-left para móvil */}
        <div className="flex-1 ml-16 lg:ml-64 p-4 md:p-6 lg:p-8">
          <div className="bg-white rounded-2xl shadow-lg p-4 md:p-6 lg:p-8">
            <div className="mb-6 md:mb-8">
              <h1 className="text-2xl md:text-3xl font-bold text-gray-900 mb-2">Tu Tienda de Confianza:</h1>
              {filters.searchTerm ? (
                <div className="flex items-center">
                  <p className="text-gray-600 text-sm md:text-base">
                    Resultados para: <span className="font-semibold text-orange-600">"{filters.searchTerm}"</span>
                  </p>
                  <button 
                    onClick={() => handleFilterChange({ searchTerm: '' })}
                    className="ml-2 text-sm text-gray-500 hover:text-orange-600"
                  >
                    (Limpiar)
                  </button>
                </div>
              ) : (
                <p className="text-gray-600 text-sm md:text-base">Descubre los mejores productos, con los mejores precios.</p>
              )}
            </div>
            
            {loading ? (
              <div className="flex flex-col items-center justify-center py-16">
                <div className="w-12 h-12 border-4 border-[#FF6B00] border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="text-gray-600 font-medium">Cargando productos...</p>
              </div>
            ) : filteredProducts.length > 0 ? (
              <>
                <div className="mb-4 md:mb-6 p-3 md:p-4 bg-gradient-to-r from-gray-50 to-gray-100 rounded-xl">
                  <p className="text-gray-700 font-medium text-sm md:text-base">
                    Mostrando <span className="text-[#FF6B00] font-bold">{filteredProducts.length}</span> de <span className="font-bold">{products.length}</span> productos
                  </p>
                </div>
                
                {/* Grid optimizado para móvil: 2 columnas en móvil, 3 en tablet, 4 en desktop */}
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-4 lg:gap-6">
                  {filteredProducts.map(product => (
                    <CardItem 
                      key={product.id} 
                      product={product} 
                      searchTerm={filters.searchTerm} 
                    />
                  ))}
                </div>
              </>
            ) : (
              <div className="col-span-full text-center py-16">
                <div className="text-gray-400 mb-4">
                  <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 16.172a4 4 0 015.656 0M9 12h6m-6-4h6m2 5.291A7.962 7.962 0 0112 15c-2.34 0-4.469-1.009-5.927-2.616M15 17H9v-2h6v2z" />
                  </svg>
                </div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">No se encontraron productos</h3>
                <p className="text-gray-500 mb-6">Prueba ajustando los filtros de búsqueda</p>
                <button
                  onClick={() => handleFilterChange({ 
                    subcategories: [], 
                    priceRange: [0, 1200],
                    searchTerm: ''
                  })}
                  className="bg-black hover:bg-gray-800 text-white px-6 py-3 rounded-xl font-medium transition-all duration-200 shadow-lg hover:shadow-xl transform hover:-translate-y-1"
                >
                  Limpiar filtros
                </button>
              </div>
            )}
            
            <div className="mt-8 md:mt-12 text-center">
              <Link to="/">
                <button className="bg-gradient-to-r from-gray-700 to-gray-900 hover:from-gray-800 hover:to-black text-white px-6 md:px-8 py-3 md:py-4 rounded-xl font-medium transition-all duration-200 shadow-lg hover:shadow-xl transform hover:-translate-y-1">
                  Volver al Inicio
                </button>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShopPage;